// Shared synthetic responses live inside the web build context so unit tests
// and browser fixtures use the same data in standalone Docker builds too. The real
// evaluator and persistence guards are exercised separately against PostgreSQL.
export const bindingRoles=['PROVIDER','RECEIVER','BASIS_CONFIRMER','REVIEWER','ARCHIVIST','DISPOSER'];
export const bindingId=n=>`85000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
export function acceptanceBindingFixture({ids,stamp,standards,selected,scenario='acceptance-sources',offset=0,selectedBinding}){
 const base=n=>({id:bindingId(n),workspaceId:ids.workspace,basisEvidenceId:ids.version,recordedBy:ids.version,createdAt:stamp,origin:'SYNTHETIC_FIXTURE',validFrom:'2020-01-01T00:00:00Z',validTo:null,state:'ACTIVE'});
 const target={deliveryOperationId:ids.deliveryOperation,datasetVersionId:ids.goldVersion};
 let responsibilities=bindingRoles.map(role=>({role,status:'UNASSIGNED',reason:'NO_BINDING',candidateIds:[],binding:null,representative:null,isCurrentCaller:false}));
 let applicability={status:selected?'MISSING':'UNSELECTED',reason:selected?'NO_APPLICABILITY_BINDING':'EXPLICIT_STANDARD_REQUIRED',candidateIds:[],binding:null};
 let history=[];
 if(scenario.startsWith('acceptance-binding-')){
  responsibilities=bindingRoles.map((role,i)=>{const representative={...base(i+1),kind:'REPRESENTATION',actorId:bindingId(100+i),subject:'synthetic-'+role.toLowerCase(),partyRef:i===0?'synthetic-provider':'synthetic-receiver'};const binding={...base(11+i),kind:'RESPONSIBILITY',role,representationId:representative.id,...target};history.push(representative,binding);return{role,status:'ASSIGNED',reason:'CURRENT_BINDING',candidateIds:[binding.id],binding,representative,isCurrentCaller:i===0};});
  const binding={...base(21),kind:'APPLICABILITY',...target,contractVersionId:ids.version,sourceSha256:'a'.repeat(64),criteriaSetHash:'b'.repeat(64),confirmerBindingId:bindingId(13)};history.push(binding);
  if(selected===ids.version)applicability={status:'MATCHED',reason:'EXACT_SOURCE_AND_CONFIRMER',candidateIds:[binding.id],binding};
  if(scenario==='acceptance-binding-expired'){const r=responsibilities[1];r.status='INACTIVE';r.reason='REPRESENTATION_NOT_CURRENT';r.isCurrentCaller=false;r.representative.validTo='2021-01-01T00:00:00Z';r.representative.state='EXPIRED';}
  if(scenario==='acceptance-binding-revoked'){const r=responsibilities[2];r.status='INACTIVE';r.reason='REPRESENTATION_NOT_CURRENT';r.representative.state='DISPOSED';history.push({...base(30),kind:'DISPOSITION',origin:undefined,targetId:r.representative.id,targetKind:'REPRESENTATION',disposition:'REVOKED',effectiveAt:stamp,reason:'合成夹具：代表资格撤销',state:'EFFECTIVE'});if(applicability.binding){applicability.status='MISMATCH';applicability.reason='SOURCE_OR_CONFIRMER_MISMATCH';}}
  if(scenario==='acceptance-binding-ambiguous'){const r=responsibilities[3];const other={...r.binding,id:bindingId(31)};history.push(other);r.candidateIds.push(other.id);r.status='AMBIGUOUS';r.reason='MULTIPLE_CURRENT_BINDINGS';r.binding=null;r.representative=null;}
  if(scenario==='acceptance-binding-conflict'){const r=responsibilities[3];r.representative.actorId=responsibilities[0].representative.actorId;r.status='CONFLICT';r.reason='PROVIDER_SEPARATION_REQUIRED';}
  if(scenario==='acceptance-binding-mismatch'&&applicability.binding){applicability.binding.criteriaSetHash='c'.repeat(64);applicability.status='MISMATCH';applicability.reason='SOURCE_OR_CONFIRMER_MISMATCH';}
  if(scenario==='acceptance-binding-replaced'){const r=responsibilities[2];history.push({...r.binding,state:'DISPOSED'});r.binding={...r.binding,id:bindingId(32)};r.candidateIds=[r.binding.id];history=history.filter(f=>f.id!==bindingId(13)||f.state==='DISPOSED');history.push(r.binding,{...base(33),kind:'DISPOSITION',origin:undefined,targetId:bindingId(13),targetKind:'RESPONSIBILITY',disposition:'SUPERSEDED',effectiveAt:stamp,reason:'合成夹具：更换确认责任',state:'EFFECTIVE'});if(applicability.binding){applicability.status='MISMATCH';applicability.reason='SOURCE_OR_CONFIRMER_MISMATCH';}}
  if(scenario==='acceptance-binding-history')for(let n=40;n<56;n++)history.push({...base(n),kind:'RESPONSIBILITY',...target,role:'RECEIVER',representationId:bindingId(2),validTo:'2021-01-01T00:00:00Z',state:'EXPIRED'});
 }
 history.sort((a,b)=>a.id.localeCompare(b.id));
 const selectedFact=selectedBinding?history.find(f=>f.id===selectedBinding):null;if(selectedBinding&&!selectedFact)return null;
 const related=[];const queue=selectedFact?[selectedFact]:[];const seen=new Set(queue.map(f=>f.kind+':'+f.id));while(queue.length){const f=queue.shift();for(const c of history){const key=c.kind+':'+c.id;const matches=f.kind==='RESPONSIBILITY'&&c.kind==='REPRESENTATION'&&f.representationId===c.id||f.kind==='APPLICABILITY'&&c.kind==='RESPONSIBILITY'&&f.confirmerBindingId===c.id||f.kind==='DISPOSITION'&&c.kind===f.targetKind&&c.id===f.targetId||c.kind==='DISPOSITION'&&c.targetKind===f.kind&&c.targetId===f.id;if(matches&&!seen.has(key)){seen.add(key);related.push(c);queue.push(c);}}}
 const receivingPartyStatus=responsibilities[1].status==='ASSIGNED'?'VERIFIED':'UNVERIFIED';
 return {workspaceId:ids.workspace,evaluatedAt:stamp,delivery:{id:ids.deliveryOperation,datasetVersionId:ids.goldVersion,status:'BLOCKED'},standards:{workspaceId:ids.workspace,items:selected?standards.filter(v=>v.id===selected):standards.slice(0,25),page:{limit:25,offset:0,total:selected?1:standards.length}},responsibilities,receivingPartyStatus,applicability,bindingHistory:{items:history.slice(offset,offset+25),page:{limit:25,offset,total:history.length},selected:selectedFact,related},writeEnabled:false,blockers:['ACCEPTANCE_WRITES_DISABLED','DELIVERY_NOT_ISSUED',...(receivingPartyStatus==='UNVERIFIED'?['RECEIVING_PARTY_UNVERIFIED']:[]),...(!selected?['EXPLICIT_STANDARD_REQUIRED']:[]),...responsibilities.filter(r=>r.status!=='ASSIGNED').map(r=>`ROLE_${r.role}_${r.status}`),...(applicability.status!=='MATCHED'?[`APPLICABILITY_${applicability.status}`]:[])]};
}
